{
  "name": "bt_scan_process",
  "confidence": "medium",
  "docstring": "Processes Bluetooth scan/channel-switching activity by selecting the next connection block, updating its scheduling state, posting state-change or HCI events when needed, and enabling the radio channel-switch timer.",
  "subsystem": "bt",
  "var_renames": {
    "a1": "msg",
    "v2": "switch_enable_ptr",
    "v4": "queue_item",
    "v6": "switch_enable",
    "v7": "cb_switch_ctrl",
    "v23": "cb_flags",
    "v24": "next_cb",
    "v25": "old_cb",
    "v26": "prev_cb",
    "v27": "cb_state",
    "v28": "timer_count_ptr",
    "v29": "timer_ctrl_ptr",
    "v31": "next_timer_count",
    "v32": "next_timer_ctrl"
  },
  "struct_hints": [
    {
      "offset": 88,
      "meaning": "cb_switch_ctrl flags byte"
    },
    {
      "offset": 40,
      "meaning": "cb_switch_ctrl previous/current connection-block pointer"
    },
    {
      "offset": 44,
      "meaning": "cb_switch_ctrl selected next connection-block pointer"
    },
    {
      "offset": 16,
      "meaning": "connection-block scheduling state (1=cleared/idle, 4=selected/busy)"
    },
    {
      "offset": 24,
      "meaning": "connection-block link-layer state; checked for 3 and <=2"
    }
  ]
}
